BEGIN;
DO $$
DECLARE admin_user_id bigint; sam_organization_id bigint; property_listing_id bigint;
BEGIN
PERFORM pg_advisory_xact_lock(hashtext('sam-import-23249'));
-- keyref is shared across different SAM properties; it is not a property identifier.
IF EXISTS (SELECT 1 FROM listing_sources WHERE upper(reference_code)='BL0106' OR source_url ~ '[?&]id=23249(&|$)') OR EXISTS (SELECT 1 FROM listings WHERE public_listing_id='a5cb59ce-bd39-4010-abf6-d98b4dc3e3e1' OR slug='sam-direct-sale-factory-office-houses-ban-chang-bl0106' OR description ILIKE '%BL0106%' OR (abs(latitude-12.722569906166047)<0.0001 AND abs(longitude-101.00134685755232)<0.0001 AND abs(land_area_sqm-5584.8)<1)) THEN RAISE NOTICE 'SAM BL0106 already exists; skipping'; RETURN; END IF;
SELECT id INTO admin_user_id FROM auth_users WHERE lower(email)='mapxprop@gmail.com' AND deleted_at IS NULL ORDER BY id LIMIT 1;
SELECT id INTO sam_organization_id FROM organizations WHERE slug='sukhumvit-asset-management-sam' AND verification_status='verified' AND is_active=true AND deleted_at IS NULL ORDER BY id LIMIT 1;
IF admin_user_id IS NULL OR sam_organization_id IS NULL THEN RAISE EXCEPTION 'Existing admin and verified SAM organization required'; END IF;

ที่ดินรูปคล้ายสี่เหลี่ยมผืนผ้า ด้านทิศเหนือติดซอยเทศบาล 48 (ซอยสระแก้ว ซอย 2) หน้ากว้างประมาณ 56 เมตร ลึกสุดประมาณ 105 เมตร ถนนสาธารณประโยชน์ผิวคอนกรีตกว้างประมาณ 6 เมตร เขตทางประมาณ 8 เมตร ต้นทางระบุเขตผังเมืองสีส้ม อยู่ในย่านที่อยู่อาศัยและเกษตรกรรม

รายการตามทะเบียนที่ SAM รับโอนมี 6 รายการ: บ้านพักอาศัยตึกชั้นครึ่งเลขที่ 96/62, โรงจอดรถ, ตึกแถวชั้นเดียว 5 คูหาไม่ปรากฏเลขทะเบียน, บ้านพักอาศัยตึกชั้นเดียวเลขที่ 96/60, อาคารสำนักงานชั้นเดียวไม่ปรากฏเลขทะเบียน และห้องน้ำ

ส่วนการสำรวจสภาพทรัพย์พบ 6 รายการ: อาคารโรงงานพร้อมสำนักงาน 1 ชั้น, อาคารสำนักงาน 1 ชั้น, บ้านพักอาศัยชั้นครึ่ง, อาคารห้องน้ำ, อาคารบ้านพักคนงาน 1 ชั้น และส่วนโล่งหลังคาคลุมจอดรถ รายการสำรวจต่างจากรายการทะเบียน โดย SAM ระบุว่าจะโอนให้ผู้ซื้อตามรายการสิ่งปลูกสร้างที่จดทะเบียนรับโอนเท่านั้น จึงต้องตรวจทะเบียน แบบแปลน ใบอนุญาต และรายการที่จะได้รับโอนให้ตรงกัน

ข้อควรทราบเรื่องการครอบครอง: SAM ระบุข้อมูล ณ วันที่ 7 มีนาคม 2568 ว่ามีผู้ใช้ประโยชน์ในทรัพย์ และขายตามสภาพ การเข้าครอบครองอาจต้องเจรจาหรือดำเนินการทางกฎหมายด้วยค่าใช้จ่ายของผู้ซื้อ ตามเงื่อนไขต้นทางไม่สามารถนำประเด็นนี้มาเป็นเหตุยกเลิกการเสนอซื้อหรือสัญญา หรือเรียกร้องจาก SAM ได้ ต้องสอบถามสถานะปัจจุบันและเงื่อนไขฉบับล่าสุดก่อนเสนอซื้อ

ข้อกำหนดด้านความสูงตามข้อมูล SAM: ทรัพย์อยู่ในเขตปลอดภัยในราชการทหารแห่งกองทัพเรือ ซึ่งต้นทางอ้างอิงข้อกำหนด พ.ศ.2536 และระบุความสูงอาคารไม่เกิน 45 เมตร อีกทั้งอยู่ในบริเวณใกล้เคียงสนามบินอู่ตะเภาตามประกาศที่ต้นทางอ้างอิง พ.ศ.2538 โดยต้องยื่นคำขอให้สำนักงานการบินพลเรือนแห่งประเทศไทยตรวจสอบข้อกำหนดความสูงที่ถูกต้อง ข้อมูล 45 เมตรนี้จึงไม่ใช่การรับรองว่าสามารถก่อสร้างได้ถึงระดับดังกล่าว และไม่ได้ยืนยันใบอนุญาตประกอบกิจการโรงงาน

การเดินทางตาม SAM: จากถนนสุขุมวิท (ทล.3) แยกอู่ตะเภา ใช้ถนนเลี่ยงเมืองสัตหีบ (ทล.332) มุ่งหน้าแยกเกษมพล ผ่านโรงเรียนพัฒเวชศึกษาและวิทยาลัยเทคโนโลยีพัฒนเวช เลี้ยวขวาเข้าถนนสำนักท้อน–สระแก้วประมาณ 960 เมตร แล้วเลี้ยวซ้ายเข้าซอยเทศบาล 48 ประมาณ 660 เมตร ทรัพย์อยู่ซ้ายมือ สถานที่ใกล้เคียงที่ต้นทางระบุ ได้แก่ โรงเรียนวัดสระแก้ว วัดสระแก้ว วิทยาลัยเทคโนโลยีพัฒนเวช และโรงเรียนพัฒเวชศึกษา

หน้า SAM แสดงสถานะซื้อตรงและราคาข้างต้น ณ วันที่ 11 กันยายน 2569 ติดต่อฝ่ายขาย SAM โทร 02-686-1888 อีเมล sales@sam.or.th หรือ LINE @samline แจ้งรหัส BL0106 เพื่อยืนยันสถานะพร้อมขาย การนัดชม ราคา การเข้าครอบครอง และเงื่อนไขล่าสุด

ใช้พิกัดผู้ดูแล 12.722569906166047, 101.00134685755232 ซึ่งใกล้เคียงหมุด SAM ภาพต้นทางแสดงวันที่ 7 มีนาคม 2568 แม้ชื่อไฟล์มีรหัสปี 69 รูปใช้ประกอบการดูสภาพในวันถ่าย ไม่ยืนยันสภาพหรือการครอบครองปัจจุบัน ต้นทางไม่ระบุพื้นที่ใช้สอยรวม จำนวนห้องนอน จำนวนห้องน้ำ จำนวนที่จอดรถ กำลังไฟฟ้า ใบอนุญาตโรงงาน หรือรายการเครื่องจักรที่รวมในการขาย จึงควรตรวจข้อมูลเหล่านี้กับ SAM โดยตรง', 22337000, false, 5584.8, 'ฝ่ายขายและส่งเสริมกิจกรรมการขาย — SAM', '026861888', 'sales@sam.or.th', '@samline', true, true, '96/60, 96/62 ซอยเทศบาล 48 (ซอยสระแก้ว ซอย 2)', 'เข้าจากถนนสำนักท้อน–สระแก้ว', 'ซอยเทศบาล 48', 12.722569906166047, 101.00134685755232, 'ระยอง', 'บ้านฉาง', 'สำนักท้อน', 'active', 'approved', now(), now(), now(), now(), true, true, 'editorial_import', 'total', 'sam-direct-sale-factory-office-houses-ban-chang-bl0106') RETURNING id INTO property_listing_id;

The roughly rectangular site has approximately 56 metres of northern frontage and a maximum depth of approximately 105 metres. The public concrete road, Soi Thetsaban 48 (Sa Kaeo Soi 2), is approximately six metres wide within an eight-metre right of way. SAM reports orange planning zoning and residential and agricultural surroundings.

Registered transferred structures: a one-and-a-half-storey house at 96/62; a garage; five single-storey shophouse units without a stated registration number; a single-storey house at 96/60; a single-storey office without a stated registration number; and a bathroom building.

Surveyed structures: a single-storey factory with office; a separate single-storey office; a one-and-a-half-storey house; a bathroom building; single-storey worker accommodation; and an open-sided covered parking area. These descriptions differ. SAM states that transfer to the buyer follows only the registered structures it acquired. Check registration, approved plans, permits and the exact transfer inventory.

Occupancy: SAM''s note dated 7 March 2025 states that people use the property. It is sold as-is. Obtaining possession may require negotiation or legal action at the buyer''s expense. Under the source terms, this issue does not entitle the buyer to cancel the offer or sale agreement or claim against SAM. Confirm current occupancy and the latest sale terms.

Height restrictions: SAM places the site within a Royal Thai Navy military safety zone, citing 1993 provisions and a stated 45-metre building height limit. It also cites 1995 provisions for the U-Tapao Airport vicinity and instructs relevant parties to request a precise height assessment from the Civil Aviation Authority of Thailand. The source''s 45-metre figure is not a guarantee of permitted construction height or confirmation of a factory operating licence.

From the U-Tapao junction on Sukhumvit Road (Highway 3), take the Sattahip bypass (Highway 332) toward Kasem Phon. Turn right into Samnak Thon–Sa Kaeo Road for approximately 960 metres, then left into Soi Thetsaban 48 for approximately 660 metres; the property is on the left. Nearby source-listed places include Wat Sa Kaeo, Wat Sa Kaeo School, Phatthanawet Technology College and Phatthawet Suksa School.

