INSERT INTO public.listing_transaction_terms (listing_id, term_code, label_th, label_en, value_th, value_en, payer_code, sort_order) VALUES (property_listing_id, 'purchase_method', 'รูปแบบการขาย', 'Sale method', 'ซื้อตรงจาก SAM รหัส BL0106 ราคา 22,337,000 บาท', 'Direct purchase from SAM, BL0106, THB 22,337,000', 'unspecified', 10) ;
INSERT INTO public.listing_transaction_terms (listing_id, term_code, label_th, label_en, value_th, value_en, payer_code, sort_order) VALUES (property_listing_id, 'occupancy', 'มีผู้ใช้ประโยชน์ในทรัพย์', 'Occupancy disclosed', 'ข้อมูล SAM ณ 7 มี.ค. 2568 ขายตามสภาพ ผู้ซื้อรับภาระเจรจาหรือดำเนินคดีเพื่อเข้าครอบครอง ต้องยืนยันสถานะและเงื่อนไขล่าสุด', 'SAM note dated 7 March 2025: sold as-is; buyer bears negotiation or legal costs for possession; confirm current status and terms', 'unspecified', 20) ;
INSERT INTO public.listing_transaction_terms (listing_id, term_code, label_th, label_en, value_th, value_en, payer_code, sort_order) VALUES (property_listing_id, 'transfer_inventory', 'รายการทะเบียนต่างจากที่สำรวจ', 'Registered and surveyed structures differ', 'SAM โอนตามรายการสิ่งปลูกสร้างที่จดทะเบียนรับโอนเท่านั้น ตรวจรายการทั้ง 6 ในรายละเอียดประกาศ', 'SAM transfers only the registered acquired structures; check both six-item lists in the description', 'unspecified', 30) ;
INSERT INTO public.listing_transaction_terms (listing_id, term_code, label_th, label_en, value_th, value_en, payer_code, sort_order) VALUES (property_listing_id, 'height_restrictions', 'เขตทหารและบริเวณใกล้สนามบิน', 'Military and airport restrictions', 'ต้นทางระบุเพดานความสูง 45 ม. และต้องขอ CAAT ตรวจความสูงที่ถูกต้อง ไม่ใช่การรับรองสิทธิก่อสร้าง', 'Source cites 45 m and requires CAAT assessment of the applicable height; no construction entitlement is implied', 'unspecified', 40) ;
INSERT INTO public.listing_transaction_terms (listing_id, term_code, label_th, label_en, value_th, value_en, payer_code, sort_order) VALUES (property_listing_id, 'permits', 'ใบอนุญาตและเครื่องจักร', 'Permits and machinery', 'ต้นทางไม่ระบุใบอนุญาตโรงงาน กำลังไฟฟ้า หรือเครื่องจักรที่รวมในการขาย ต้องยืนยันกับ SAM', 'Factory permits, electrical capacity and machinery included in the sale are not published; confirm with SAM', 'unspecified', 50) ;
