INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=23249&keyref=6007623', 'BL0106', now(), 'Official SAM page captured 2026-09-11. Direct purchase THB 22,337,000, three plots, 5,584.8 sq.m. Registered and surveyed building inventories differ; SAM transfers registered structures only. Occupancy note dated 2025-03-07 and buyer possession obligations retained. Military safety zone, source-stated 45 m limit and separate CAAT airport height assessment retained as source claims. Photos display 2025-03-07 despite filenames using year code 69. All 23 images preserved and optimized without retouching; factory image chosen as cover. All-status duplicate search by property code, page ID, deeds, address, area and nearby coordinates found no matches. keyref=6007623 is shared with other properties and is deliberately not used as a unique identifier.') ;
INSERT INTO public.listing_translations (listing_id, language_code, title, description, address_line1, address_line2, road, subdistrict_name, district_name, province_name, seo_title, seo_description, translation_status, translation_source, reviewed_at, search_text) VALUES (property_listing_id, 'en', 'SAM Direct Sale: Factory, Offices and Houses on 3 Rai in Ban Chang, THB 22.337M', 'Factory/warehouse premises with offices and residential buildings at 96/60 and 96/62, Samnak Thon, Ban Chang, Rayong. Three adjoining plots, deeds 14450, 14451 and 46654, total 3 rai 1 ngan 96.2 sq.wah (1,396.2 sq.wah / 5,584.8 sq.m.). SAM announced price THB 22,337,000; asset BL0106.
INSERT INTO public.organization_verifications (organization_id, verification_type, status, source_url, evidence_note, reviewed_by_user_id, reviewed_at) VALUES (sam_organization_id, 'listing_authority', 'verified', 'https://www.sam.or.th/site/npa/detail.php?id=23249&keyref=6007623', 'Official SAM NPA page 23249 identifies SAM as asset holder and direct-sale contact for BL0106.', admin_user_id, now()) ;
INSERT INTO public.organization_audit_logs (organization_id, actor_user_id, action_code, entity_type, entity_public_id, metadata) VALUES (sam_organization_id, admin_user_id, 'listing.publisher_verified', 'listing', 'a5cb59ce-bd39-4010-abf6-d98b4dc3e3e1', '{"reference_code":"BL0106","source_page_id":23249,"source_image_count":23,"occupancy_disclosed":true,"building_discrepancy_disclosed":true,"height_restrictions_disclosed":true,"duplicate_check":"no matches; keyref is not unique"}'::jsonb) ;
